import sqlite3

def archivia(con, prove):
    con.execute("CREATE TABLE IF NOT EXISTS prove (provino TEXT UNIQUE, materiale TEXT, Rm REAL)")
    with con:
        con.executemany("INSERT INTO prove VALUES (?, ?, ?)", prove)
    return con.execute("SELECT COUNT(*) FROM prove").fetchone()[0]

def media_per_materiale(con):
    return dict(con.execute("SELECT materiale, AVG(Rm) FROM prove GROUP BY materiale").fetchall())

con = sqlite3.connect(":memory:")
print(archivia(con, [("P1", "S355", 510.0), ("P2", "S355", 500.0)]))
